import{z as s,x as A,o as B,c as p,q as o,j as t,D as e,d as r,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"李嘉图比较优势","description":"","frontmatter":{"title":"李嘉图比较优势","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ricardian-comparative-advantage.md","filePath":"econ/ricardian-comparative-advantage.md","lastUpdated":1791063341000}'),C={name:"econ/ricardian-comparative-advantage.md"};function d(c,a,m,_,h,u){const n=A("Mermaid");return B(),p("div",null,[a[2]||(a[2]=o('<h1 id="李嘉图比较优势" tabindex="-1">李嘉图比较优势 <a class="header-anchor" href="#李嘉图比较优势" aria-label="Permalink to &quot;李嘉图比较优势&quot;">​</a></h1><div class="epigraph"><p>一国可以在所有产品上都更差，仍应出口相对更不差的那种；贸易的增益来自机会成本差，不是绝对成本差。</p><footer>—— Ricardo, On the Principles of Political Economy and Taxation, 1817</footer></div><p><a href="/econ/multi-period-consumption-portfolio">上一课</a>把消费–组合收回到离散多期，信息、流动性与无套利课程就此收束：信息核、无套利核、摩擦核、组合核已经对齐。本课是「贸易与国际金融」的第一课，换对象：为何交换、资本如何流。开放宏观主干已经有<a href="/econ/open-ca">经常账户</a>与三角，但没有把<strong>货物如何在两国间分工</strong>写成理论。后课默认已经读完：比较优势是机会成本，不是「谁更勤劳」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两商品、两国家、劳动一种要素、规模报酬不变。本国两种产品的劳动投入 \\(a_{L1},a_{L2}\\)，外国 \\(a_{L1}^*,a_{L2}^*\\)。绝对优势是 \\(a_{Li}\\lt a_{Li}^*\\)。比较优势是相对</p> \\[\\frac{a_{L1}}{a_{L2}}\\lt \\frac{a_{L1}^*}{a_{L2}^*}, \\]<p>即本国产 1 的机会成本更低。即便 \\(a_{L1}\\gt a_{L1}^*\\) 且 \\(a_{L2}\\gt a_{L2}^*\\)，只要不等式成立，本国仍应出口 1。缺口不是再讲开放会计，而是：贸易增益来自<strong>相对</strong>劳动生产率，闭关等于强迫每个经济体按本国消费比例生产，把机会成本差浪费掉。</p><p><span class="marginnote">机会成本翻译成大白话：多造 1 单位布，就得少造多少酒。比较优势问的不是「谁造得快」，而是「谁放弃得少」。两国各盯住自己放弃得少的那样东西去生产，交换后的总盘子比各自硬撑着两样都造要大。</span></p><p><span class="marginnote">葡萄牙与英格兰的呢绒–葡萄酒是李嘉图的例子。现代写法用单位劳动需求 \\(a_{Li}\\)。Dornbusch–Fischer–Samuelson 把连续商品写进同一逻辑，本课先停在两商品。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>封闭时相对价格钉在机会成本上。开放、零运输成本、完全竞争：世界相对价格夹在两国机会成本之间（大国可影响世界价格，小国接受世界价格）。完全分工（除非世界价格刚好等于某国机会成本）。劳动在国内可流动、国际不可流动——要素下一课才跨境含义。福利：两国消费可能超出本国生产可能集，贸易是一种技术。</p>',11)),(B(),t(l,null,{default:e(()=>[i(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20OC%5B%22%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%E5%B7%AE%22%5D%20--%3E%20CA%5B%22%E6%AF%94%E8%BE%83%E4%BC%98%E5%8A%BF%22%5D%0A%20%20AA%5B%22%E7%BB%9D%E5%AF%B9%E4%BC%98%E5%8A%BF%22%5D%20--%3E%20WAGE%5B%22%E5%8F%AA%E5%AE%9A%E5%B7%A5%E8%B5%84%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20CA%20--%3E%20SPEC%5B%22%E5%88%86%E5%B7%A5%E4%B8%8E%E5%87%BA%E5%8F%A3%22%5D%0A%20%20SPEC%20--%3E%20GAIN%5B%22%E6%B6%88%E8%B4%B9%E8%B6%85%E5%87%BA%E6%9C%AC%E5%9B%BD%20PPF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"计量课的因果语言在此用不上：这是均衡比较静态，不是 ATT。后课 China shock 才会把贸易暴露当处理。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是相对价格。贸易把本国稀缺的那种机会成本「进口」进来。工资由绝对优势定水平：两国都生产时，工资比等于绝对劳动生产率比；完全分工时工资比落在一个区间。绝对落后的国家工资更低，正是它出口比较优势产品的通道，不是「不该贸易」的理由。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：设本国造 1 单位布要 6 小时、1 单位酒要 4 小时；外国只要 5 小时与 2 小时。外国样样更快（绝对优势），但 1 单位布在本国相当于放弃 1.5 单位酒，在外国相当于放弃 2.5 单位酒——本国造布「放弃得少」，于是布由本国出口，酒由外国出口。")],-1)),(B(),t(l,null,{default:e(()=>[i(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E6%9C%AC%E5%9B%BD%EF%BC%9A%E5%B8%83%206%20%E5%B0%8F%E6%97%B6%E3%80%81%E9%85%92%204%20%E5%B0%8F%E6%97%B6%22%5D%20--%3E%20HC%5B%22%E6%9C%AC%E5%9B%BD%201%20%E5%B8%83%E7%9A%84%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%EF%BC%9A1.5%20%E9%85%92%22%5D%0A%20%20F%5B%22%E5%A4%96%E5%9B%BD%EF%BC%9A%E5%B8%83%205%20%E5%B0%8F%E6%97%B6%E3%80%81%E9%85%92%202%20%E5%B0%8F%E6%97%B6%22%5D%20--%3E%20FC%5B%22%E5%A4%96%E5%9B%BD%201%20%E5%B8%83%E7%9A%84%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%EF%BC%9A2.5%20%E9%85%92%22%5D%0A%20%20HC%20--%3E%20CMP%5B%22%E6%9C%AC%E5%9B%BD%E6%94%BE%E5%BC%83%E6%9B%B4%E5%B0%91%EF%BC%9A%E5%B8%83%E7%9A%84%E6%AF%94%E8%BE%83%E4%BC%98%E5%8A%BF%E5%9C%A8%E6%9C%AC%E5%9B%BD%22%5D%0A%20%20FC%20--%3E%20CMP%0A%20%20CMP%20--%3E%20SPEC%5B%22%E6%9C%AC%E5%9B%BD%E4%B8%93%E9%80%A0%E5%B8%83%EF%BC%8C%E5%A4%96%E5%9B%BD%E4%B8%93%E9%80%A0%E9%85%92%22%5D%0A%20%20SPEC%20--%3E%20GAIN%5B%22%E4%B8%96%E7%95%8C%E6%80%BB%E4%BA%A7%E5%87%BA%E5%8F%98%E5%A4%A7%EF%BC%8C%E4%B8%A4%E5%9B%BD%E6%B6%88%E8%B4%B9%E8%B6%8A%E8%BF%87%E6%9C%AC%E5%9B%BD%20PPF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>与<a href="/econ/open-ca">开放经常账户</a>：李嘉图是实物分工，可以发生在平衡贸易上。\\(CA\\neq 0\\) 是跨期，不是比较优势的必要条件。本课默认平衡贸易，把跨期留给国际金融续。</p><p><span class="marginnote">比较成本不是劳动价值论的复活课。现代转述只用机会成本与 PPF。Mill、Marshall 补需求边决定贸易条件；本课供给边先钉住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>一种要素解释不了要素密集度与收入分配——那是 Heckscher–Ohlin 与 Stolper–Samuelson。规模报酬与差异产品是 Krugman。异质企业是 Melitz。运输成本一高，分工区间缩小，不必到零贸易。本课不估贸易弹性，不把引力方程提前写完。</p><p><span class="marginnote">直觉类比：一位律师自己修水管可能比水管工还快（绝对优势），但律师的一小时值几百块，修水管要搭进去的时间太贵，所以仍然雇水管工，自己去做案子。每个经济体都在做同样的算账：把劳动放在「放弃最少」的用途上，剩下的靠交换。</span></p><p>后课默认：两国交换的最低理由是机会成本差；绝对劣势不禁止出口。要素禀赋下一课。不要用「我们什么都更贵所以不该开放」当政策句——那是把绝对优势误读成比较优势。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>比较优势是相对机会成本，不是绝对生产率。</li><li>开放相对价格夹在两国成本之间，导致分工。</li><li>工资水平跟绝对优势走；贸易增益跟相对优势走。</li><li>平衡贸易即可；经常账户是另一套跨期。</li><li>出处：Ricardo, <em>Principles</em> 1817；Dornbusch–Fischer–Samuelson 连续商品推广。</li></ul>',8))])}const F=s(C,[["render",d]]);export{f as __pageData,F as default};
